<style>
:root{color-scheme:dark;--bg:#101114;--panel:#191b20;--line:#2a2d34;--text:#f4f5f7;--muted:#969ba6;--accent:#d8ff45}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px/1.5 Inter,system-ui,sans-serif}a{color:inherit;text-decoration:none}.shell{max-width:1120px;margin:auto;padding:0 26px}header{height:78px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between}.brand{font-size:21px;font-weight:900;letter-spacing:.12em}.brand span{color:var(--accent)}.logout{background:transparent;border:1px solid #454952;color:var(--text);border-radius:8px;padding:9px 14px;cursor:pointer}.intro{padding:54px 0 34px}.muted{color:var(--muted)}.eyebrow{color:var(--accent);font-size:12px;font-weight:800;letter-spacing:.15em;text-transform:uppercase}h1{font-size:40px;letter-spacing:-.05em;margin:10px 0}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.stat,.block{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:22px}.stat strong{display:block;font-size:32px}.stat span{color:var(--muted);font-size:13px}.block{margin-top:18px}.block h2{margin:0 0 8px;font-size:20px}.success{color:var(--accent);margin-top:10px}.items{display:grid;gap:10px;margin-top:14px}.item{border:1px solid var(--line);border-radius:8px;padding:13px 15px;display:flex;justify-content:space-between;gap:15px}.role{display:inline-block;border:1px solid #4b5037;color:var(--accent);border-radius:20px;padding:4px 10px;font-size:12px}@media(max-width:650px){.shell{padding:0 17px}.stats{grid-template-columns:1fr}.intro{padding-top:38px}}
/* ARENA-X-MOTION-POLISH */

body{background-image:radial-gradient(ellipse at 85% 4%,#d8ff4510,transparent 34%),radial-gradient(ellipse at 5% 55%,#5474ff0b,transparent 32%)}header{animation:fadeDown .5s both}.intro{animation:rise .6s .08s both}.stat,.block{transition:transform .22s,border-color .22s,box-shadow .22s;animation:rise .55s both}.stat:hover,.block:hover{border-color:#444b31;box-shadow:0 12px 32px #0003}.stat:hover{transform:translateY(-3px)}.item{transition:background .2s,border-color .2s,transform .2s}.item:hover{background:#ffffff08;border-color:#535b38;transform:translateX(3px)}.logout{transition:all .2s}.logout:hover{border-color:var(--accent);color:var(--accent)}@keyframes fadeDown{from{opacity:0;transform:translateY(-10px)}to{opacity:1;transform:none}}@keyframes rise{from{opacity:0;transform:translateY(15px)}to{opacity:1;transform:none}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation-duration:.01ms!important;transition-duration:.01ms!important}}
